import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Card, CardBody, Col, Input, Row } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import { fetchSchoolEmployeesApi } from 'actions/admin/employees';
import {
  assignSubjectTeacherApi,
  assignSubjectTeachersApi,
  fetchSubjectTeachersApi,
  removeSubjectTeacherApi,
} from 'actions/admin/onboarding';
import { showToast } from 'actions/admin/auth';
import { employeeStatic } from 'config/constants';
import { formResMessage, getGlobalSchoolUtils } from 'utils/commonFunc';
import { useChainWheel } from 'utils/useContainWheel';
import { useTenRowsHeight } from '../Common/TableFrame';
import { cacheGet, cacheSet } from 'utils/softCache';
import { explainApiError } from 'utils/schoolSetup';
import {
  SHOW,
  assignSummary,
  countByTeacher,
  filterOptions,
  filterSubjects,
  toggleRange,
} from 'utils/subjectAssignment';
import ConfirmModal from '../Common/ConfirmModal';
import EmptyState from '../Common/EmptyState';
import { SkeletonRows } from '../Common/Loader';
import SetupNeeded from '../Common/SetupNeeded';
import FilterSelect from '../Common/FilterSelect';

const EMPTY_FILTERS = { courseId: '', subjectName: '', show: SHOW.UNASSIGNED, text: '' };

// The admin's way to say who teaches what: pick a teacher on the left, tick subjects on the right (filter by class or subject, or
// search), then assign them all at once. It is the one place subjects get a teacher - the app's teachers only see theirs.
const AssignSubjectsPage = () => {
  const dispatch = useDispatch();
  const token = useSelector(state => state.auth.loggedUserToken);
  const schoolId = getGlobalSchoolUtils()?.schoolId;
  const api = useMemo(() => ({ token, schoolId }), [token, schoolId]);

  // what this school showed last time is on screen at once; the fresh copy is read behind it (no skeleton when switching tabs)
  const cacheKey = `assign:${schoolId}`;
  const cached = cacheGet(cacheKey);
  const [teachers, setTeachers] = useState(cached?.teachers || []);
  const [subjects, setSubjects] = useState(cached?.subjects || []);
  const [loading, setLoading] = useState(!cached);
  const [busy, setBusy] = useState(false);
  const [teacherText, setTeacherText] = useState('');
  const [mineOpen, setMineOpen] = useState(false); // the chosen teacher's subjects: first few, or all of them
  const [onlyFree, setOnlyFree] = useState(false); // only the teachers who have no subject yet
  const [activeId, setActiveId] = useState(null);
  const [filters, setFilters] = useState(EMPTY_FILTERS);
  const [ticked, setTicked] = useState({});
  const [lastIndex, setLastIndex] = useState(null);
  const [confirm, setConfirm] = useState(null);

  const toast = useCallback((message, type) => dispatch(showToast(message, type)), [dispatch]);
  const teacherListRef = useRef(null);
  const tableRef = useRef(null);
  useChainWheel(teacherListRef);
  useChainWheel(tableRef);
  // like every list table: ten rows in full, a longer list scrolls under its header
  const tableHeight = useTenRowsHeight(tableRef);

  const loadSubjects = useCallback(
    () =>
      fetchSubjectTeachersApi(api).then(rows => {
        const list = Array.isArray(rows) ? rows : [];
        setSubjects(list);
        cacheSet(`assign:${schoolId}`, { ...cacheGet(`assign:${schoolId}`), subjects: list });
      }),
    [api, schoolId]
  );

  useEffect(() => {
    if (!schoolId) {
      setLoading(false);
      return;
    }
    Promise.all([fetchSchoolEmployeesApi({ ...api, profession: 'TEACHING' }), loadSubjects()])
      .then(([list]) => {
        const teacherList = Array.isArray(list) ? list : [];
        setTeachers(teacherList);
        cacheSet(`assign:${schoolId}`, { ...cacheGet(`assign:${schoolId}`), teachers: teacherList });
      })
      .catch(err => toast(explainApiError(err, formResMessage(err)), 'error'))
      .finally(() => setLoading(false));
  }, [api, schoolId, loadSubjects, toast]);

  const counts = useMemo(() => countByTeacher(subjects), [subjects]);
  const options = useMemo(() => filterOptions(subjects), [subjects]);
  const visible = useMemo(() => filterSubjects(subjects, filters, activeId), [subjects, filters, activeId]);
  const active = teachers.find(t => String(t.employeeId) === String(activeId));
  const tickedRows = visible.filter(row => ticked[row.subjectId]);
  // what the chosen teacher teaches now: shown in the box above the filters, so an assignment is seen the moment it is made
  const mine = active ? subjects.filter(row => String(row.employeeId) === String(activeId)) : [];
  const MINE_SHOWN = 3;
  const shownMine = mineOpen ? mine : mine.slice(0, MINE_SHOWN);
  const freeCount = teachers.filter(t => !counts[t.employeeId]).length;
  const shownTeachers = teachers
    .filter(t => `${t.name} ${t.code || ''}`.toLowerCase().includes(teacherText.trim().toLowerCase()))
    .filter(t => !onlyFree || !counts[t.employeeId])
    .sort((a, b) => String(a.name).localeCompare(String(b.name)));

  const setFilter = patch => setFilters(prev => ({ ...prev, ...patch }));

  const clickRow = (event, index) => {
    const row = visible[index];
    setTicked(prev =>
      event.shiftKey && lastIndex !== null && visible[lastIndex]
        ? toggleRange(prev, visible, lastIndex, index)
        : (() => {
            const next = { ...prev };
            if (next[row.subjectId]) delete next[row.subjectId];
            else next[row.subjectId] = true;
            return next;
          })()
    );
    setLastIndex(index);
  };

  const run = async (work, doneMessage) => {
    setBusy(true);
    try {
      await work();
      await loadSubjects();
      setTicked({});
      setLastIndex(null);
      if (doneMessage) toast(doneMessage, 'success');
    } catch (err) {
      toast(explainApiError(err, formResMessage(err)), 'error');
    } finally {
      setBusy(false);
      setConfirm(null);
    }
  };

  const needTeacher = () => {
    if (!active) toast(`Select a ${employeeStatic.toLowerCase()} on the left first.`, 'warning');
    return !!active;
  };

  const assignOne = row => {
    if (!needTeacher()) return;
    const replace = row.employeeId && String(row.employeeId) !== String(activeId);
    const go = () =>
      run(
        () => assignSubjectTeacherApi({ ...api, subjectId: row.subjectId, employeeId: Number(activeId) }),
        `${row.subjectName} (${row.courseName}) assigned to ${active.name}`
      );
    if (replace) {
      setConfirm({
        message: `${row.subjectName} (${row.courseName}) already has ${row.teacherName}. Replace with ${active.name}?`,
        onYes: go,
      });
    } else {
      go();
    }
  };

  const assignTicked = () => {
    if (!needTeacher()) return;
    if (!tickedRows.length) {
      toast('Tick some subjects first (click rows, or use "Tick all shown").', 'warning');
      return;
    }
    const { total, replacing } = assignSummary(tickedRows, activeId);
    setConfirm({
      message: `Assign ${total} subject(s) to ${active.name}?${
        replacing ? ` ${replacing} already have another ${employeeStatic.toLowerCase()} and will be replaced.` : ''
      }`,
      onYes: () =>
        run(async () => {
          const result = await assignSubjectTeachersApi({
            ...api,
            items: tickedRows.map(row => ({ subjectId: row.subjectId, employeeId: Number(activeId) })),
          });
          if (result?.errors?.length) toast(`Some failed: ${result.errors.join(', ')}`, 'error');
        }, `${total} subject(s) assigned to ${active.name}`),
    });
  };

  const removeOne = row =>
    setConfirm({
      message: `Remove ${row.subjectName} (${row.courseName}) from ${active.name}?`,
      onYes: () =>
        run(
          () => removeSubjectTeacherApi({ ...api, subjectId: row.subjectId }),
          `${row.subjectName} (${row.courseName}) removed from ${active.name}`
        ),
    });

  const removeTicked = () => {
    const rows = tickedRows.filter(row => row.employeeId);
    if (!rows.length) {
      toast(`None of the ticked subjects has a ${employeeStatic.toLowerCase()}.`, 'warning');
      return;
    }
    setConfirm({
      message: `Remove the ${employeeStatic.toLowerCase()} from ${rows.length} subject(s)?`,
      onYes: () =>
        run(
          () => Promise.all(rows.map(row => removeSubjectTeacherApi({ ...api, subjectId: row.subjectId }))),
          `${employeeStatic} removed from ${rows.length} subject(s)`
        ),
    });
  };

  if (!schoolId) return <EmptyState title="Please select a school first" />;
  // nothing of the page is drawn until the lists are here (an empty table flashing first looked like a bug)
  if (loading) {
    return (
      <Card>
        <CardBody>
          <SkeletonRows rows={6} />
        </CardBody>
      </Card>
    );
  }
  if (!subjects.length) return <SetupNeeded what="classes or subjects" />;

  return (
    <>
      <Row>
        <Col lg="3" md="4" className="mb-3">
          <Card style={{ position: 'sticky', top: 70 }}>
            <CardBody>
              <div style={{ fontWeight: 700, marginBottom: 8 }}>1. Pick a {employeeStatic.toLowerCase()}</div>
              <Input
                bsSize="sm"
                placeholder={`Search ${employeeStatic.toLowerCase()} name / code`}
                value={teacherText}
                onChange={e => setTeacherText(e.target.value)}
              />
              <div className="rui-chips">
                <button type="button" className={onlyFree ? '' : 'on'} onClick={() => setOnlyFree(false)}>
                  All ({teachers.length})
                </button>
                <button
                  type="button"
                  className={onlyFree ? 'on' : ''}
                  title={`${employeeStatic}s who have no subject yet`}
                  onClick={() => setOnlyFree(true)}>
                  Unassigned ({freeCount})
                </button>
              </div>
              <div ref={teacherListRef} className="rui-teacher-list">
                {shownTeachers.map(t => {
                  const selected = String(t.employeeId) === String(activeId);
                  return (
                    <div
                      key={t.employeeId}
                      role="button"
                      tabIndex={0}
                      onClick={() => setActiveId(t.employeeId)}
                      onKeyDown={e => e.key === 'Enter' && setActiveId(t.employeeId)}
                      style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        gap: 8,
                        padding: '8px 10px',
                        marginTop: 6,
                        borderRadius: 12,
                        cursor: 'pointer',
                        border: `1px solid ${selected ? colors.accent : '#e8e3f0'}`,
                        background: selected ? colors.accent : '#fff',
                        color: selected ? '#fff' : '#1b1030',
                      }}>
                      <span>
                        {t.name}
                        {t.code && (
                          <small style={{ display: 'block', color: selected ? '#e5d4f5' : '#9ca3af' }}>{t.code}</small>
                        )}
                      </span>
                      <span
                        title={counts[t.employeeId] ? 'subjects assigned' : 'no subject yet'}
                        style={{
                          alignSelf: 'center',
                          minWidth: 24,
                          textAlign: 'center',
                          padding: '0 7px',
                          borderRadius: 999,
                          fontSize: 12,
                          fontWeight: 700,
                          background: counts[t.employeeId] ? (selected ? '#ede1f7' : '#f1ecf7') : '#ffe8b8',
                          color: counts[t.employeeId] ? '#1b1030' : '#8a5a00',
                        }}>
                        {counts[t.employeeId] || 0}
                      </span>
                    </div>
                  );
                })}
                {!loading && !shownTeachers.length && (
                  <div className="text-muted mt-2">
                    {onlyFree && !teacherText
                      ? `Every ${employeeStatic.toLowerCase()} has a subject.`
                      : `No ${employeeStatic.toLowerCase()}s found.`}
                  </div>
                )}
              </div>
            </CardBody>
          </Card>
        </Col>

        <Col lg="9" md="8">
          <div
            style={{
              padding: '10px 14px',
              borderRadius: 14,
              marginBottom: 14,
              background: active ? '#e2ffde' : '#fff4e0',
              border: `1px solid ${active ? '#8fd18a' : '#f5b84a'}`,
            }}>
            {active ? (
              <>
                Assigning to: <b>{active.name}</b>{' '}
                <span className="text-muted">
                  ({mine.length} subject{mine.length === 1 ? '' : 's'} now)
                </span>
                <div className={`rui-mine${mineOpen ? ' open' : ''}`}>
                  {mine.length ? (
                    shownMine.map(row => (
                      <span key={row.subjectId} className="rui-mine-chip">
                        <span className="rui-mine-text">
                          {row.courseName} · {row.subjectName}
                        </span>
                        <button
                          type="button"
                          aria-label={`Remove ${row.subjectName} (${row.courseName}) from ${active.name}`}
                          title="Remove"
                          disabled={busy}
                          onClick={() => removeOne(row)}>
                          <svg width="8" height="8" viewBox="0 0 8 8" aria-hidden="true">
                            <path d="M1 1l6 6M7 1L1 7" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" />
                          </svg>
                        </button>
                      </span>
                    ))
                  ) : (
                    <span className="text-muted" style={{ fontSize: 12 }}>
                      No subjects yet. Tick subjects below and press Assign; they will show here.
                    </span>
                  )}
                  {mine.length > MINE_SHOWN && (
                    <button type="button" className="rui-mine-more" onClick={() => setMineOpen(open => !open)}>
                      {mineOpen ? 'Show less' : `+${mine.length - MINE_SHOWN} more`}
                    </button>
                  )}
                </div>
              </>
            ) : (
              `No ${employeeStatic.toLowerCase()} selected - click one on the left.`
            )}
          </div>

          <Card>
            <CardBody>
              <div className="d-flex align-items-center justify-content-between" style={{ marginBottom: 8 }}>
                <div style={{ fontWeight: 700 }}>2. Find subjects</div>
                <CustomButton size="small" variant="outlined" name="Reset" onClick={() => setFilters(EMPTY_FILTERS)} />
              </div>
              <Row form>
                <Col md="3" className="mb-2">
                  <label>Class</label>
                  <FilterSelect
                    options={options.classes}
                    value={filters.courseId}
                    placeholder="All classes"
                    onChange={courseId => setFilter({ courseId })}
                  />
                </Col>
                <Col md="3" className="mb-2">
                  <label>Subject</label>
                  <FilterSelect
                    options={options.subjects.map(name => ({ value: name, label: name }))}
                    value={filters.subjectName}
                    placeholder="All subjects"
                    onChange={subjectName => setFilter({ subjectName })}
                  />
                </Col>
                <Col md="3" className="mb-2">
                  <label>Show</label>
                  <FilterSelect
                    searchable={false}
                    clearable={false}
                    options={[
                      { value: SHOW.ALL, label: 'All' },
                      { value: SHOW.UNASSIGNED, label: 'Not assigned yet' },
                      { value: SHOW.ASSIGNED, label: 'Already assigned' },
                      { value: SHOW.MINE, label: `Selected ${employeeStatic.toLowerCase()}'s` },
                      { value: SHOW.OTHERS, label: 'Assigned to others' },
                    ]}
                    value={filters.show}
                    onChange={show => setFilter({ show })}
                  />
                </Col>
                <Col md="3" className="mb-2">
                  <label>Search</label>
                  <Input
                    value={filters.text}
                    placeholder={`class, subject or ${employeeStatic.toLowerCase()}`}
                    onChange={e => setFilter({ text: e.target.value })}
                  />
                </Col>
              </Row>
            </CardBody>
          </Card>

          <Card>
            <CardBody>
              <div className="d-flex flex-wrap align-items-center" style={{ gap: 8, marginBottom: 8 }}>
                <b>3. Assign</b>
                <CustomButton
                  size="small"
                  variant="outlined"
                  name="Tick all shown"
                  onClick={() => setTicked(Object.fromEntries(visible.map(r => [r.subjectId, true])))}
                />
                <CustomButton size="small" variant="outlined" name="Untick all" onClick={() => setTicked({})} />
                <CustomButton
                  size="small"
                  disabled={busy}
                  onClick={assignTicked}
                  name={`Assign ticked → ${active ? active.name : employeeStatic.toLowerCase()}`}
                />
                <CustomButton
                  size="small"
                  variant="outlined"
                  disabled={busy}
                  onClick={removeTicked}
                  name={`Remove ${employeeStatic.toLowerCase()} from ticked`}
                />
                <span className="text-muted" style={{ fontSize: 12 }}>
                  {visible.length} shown / {subjects.length} total, {tickedRows.length} ticked
                </span>
              </div>
              <div className="text-muted" style={{ fontSize: 12, marginBottom: 8 }}>
                Tip: click a row to tick it (Shift + click for a range). A row&apos;s own <b>Assign</b> button saves
                just that subject.
              </div>
              <div ref={tableRef} className="rui-scrollarea" style={{ maxHeight: tableHeight || 'none' }}>
                <table className="table" style={{ marginBottom: 0 }}>
                  <thead>
                    <tr>
                      <th style={{ width: 34 }} />
                      <th>Class</th>
                      <th>Subject</th>
                      <th>Current {employeeStatic.toLowerCase()}</th>
                      <th style={{ width: 90 }} />
                    </tr>
                  </thead>
                  <tbody>
                    {visible.map((row, index) => (
                      <tr
                        key={row.subjectId}
                        onClick={event => clickRow(event, index)}
                        style={{
                          cursor: 'pointer',
                          userSelect: 'none',
                          background: ticked[row.subjectId]
                            ? '#ede1f7'
                            : String(row.employeeId) === String(activeId)
                            ? '#e2ffde'
                            : undefined,
                        }}>
                        <td>
                          <span className={`rui-check${ticked[row.subjectId] ? ' on' : ''}`} aria-hidden="true" />
                        </td>
                        <td>{row.courseName}</td>
                        <td>
                          {row.subjectName} <small className="text-muted">{row.subjectCode}</small>
                        </td>
                        <td style={{ color: row.employeeId ? undefined : '#b45309' }}>
                          {row.employeeId ? row.teacherName : '— none —'}
                        </td>
                        <td>
                          <span
                            role="presentation"
                            onClick={event => {
                              event.stopPropagation();
                              assignOne(row);
                            }}>
                            <CustomButton size="small" variant="outlined" name="Assign" disabled={busy} />
                          </span>
                        </td>
                      </tr>
                    ))}
                    {!visible.length && (
                      <tr>
                        <td colSpan="5" className="text-muted">
                          {loading ? 'Loading...' : 'No subjects match the filters.'}
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </CardBody>
          </Card>
        </Col>
      </Row>
      <ConfirmModal
        size="md"
        loading={busy}
        confirmModalOpen={!!confirm}
        confirmMessage={confirm?.message}
        deleteConfirm={() => confirm?.onYes()}
        deleteCancel={() => setConfirm(null)}
      />
    </>
  );
};

export default AssignSubjectsPage;
