import React from 'react';
import { connect } from 'react-redux';
import { withRouter } from 'react-router-dom';
import { Input } from 'reactstrap';
import {
  saveSubjectService,
  fetchSubjectService,
  updateSubjectService,
  deleteSubjectService,
  fetchCourseSubjectsService,
  fetchBatchSubjectsApi,
} from 'actions/admin/subjects';
import { fetchGenSubjectAndCodesService } from 'actions/admin/config';
import { fetchBatchCourseService } from 'actions/admin/courses';
import { fetchCurrentBatchByYearService } from 'actions/admin/batches';
import { fetchSchoolEmployeesApi, fetchAllEmpAssignSubjectsService } from 'actions/admin/employees';
import { store } from 'index';
import { cacheGet, cacheSet } from 'utils/softCache';
import SubjectFormModal from './components/SubjectFormModal.jsx';
import {
  formResMessage,
  getCurrentYearBatchUtils,
  getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
} from '../../../utils/commonFunc.js';
import { showToast } from '../../../actions/admin/auth.js';
import constants, { coursesStatic, employeeStatic } from '../../../config/constants.js';
import MuiTable from '../Common/MuiTable.jsx';
import FilterSelect from '../Common/FilterSelect';
import CustomButton from '../../../components/CustomButton';
import AssignTeacherSubjectModal from './components/AssignTeacherSubjectModal.jsx';

// Every subject of every class of the batch in one table (class, subject, teacher), with a summary above it and filters: class,
// search, "no teacher yet". Admins add, edit and give a subject its teacher. A teacher sees the same table but can change
// nothing: no add / edit / assign controls, no dialogs. (Who has no subject yet is on the Teacher subjects tab.)
// This hides the controls only - the backend does not check the role on these endpoints.
class SubjectPage extends React.Component {
  constructor() {
    super();
    // what this school's batch showed last time is shown at once while the fresh copy is read behind it
    const cached = cacheGet(this.cacheKey());
    this.state = {
      schoolId: null,
      isModalOpen: false,
      courseId: null,
      courseSubjectsFetching: false,
      allSubjects: cached?.allSubjects || [],
      allSubjectsFetching: !cached,
      filterClass: '',
      filterText: '',
      onlyNoTeacher: false,
      isAssignTeacherModalOpen: false,
      assignTeacherSubject: null,
      // Fetched into local state, not the shared state.employees.employeeList redux slice -
      // Staff Attendance/Teacher Subjects/Reports etc. all write into that same slot with
      // whatever profession they last fetched, so reading it here after visiting one of those
      // pages could silently show workers in what's meant to be a teachers-only list.
      employees: cached?.employees || [],
    };
  }

  cacheKey = () => `subjects:${getGlobalSchoolUtils()?.schoolId}:${getGlobalCurrentBatchUtils().batchId}`;

  isLoading = (name, value) => this.setState({ [name]: value });

  isReadOnly = () => this.props.loggedUserRole === constants.roles.teacher;

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool) {
      this.setState({ schoolId: globalSchool.schoolId });
      this.fetchGenSubjectAndCodes(globalSchool);
      // the classes need the batch: when it is not known yet (a fresh login, or the saved choice is gone) it is looked up first
      this.ensureBatch().then(() => {
        this.fetchBatchClassAndSubjects();
        this.loadAllSubjects();
      });
      fetchSchoolEmployeesApi({
        schoolId: globalSchool.schoolId,
        token: this.props.loggedUserToken,
        profession: 'TEACHING',
      }).then(employees => {
        this.setState({ employees: employees || [] });
        cacheSet(this.cacheKey(), { ...cacheGet(this.cacheKey()), employees: employees || [] });
      });
      if (!this.props.empAssignSubjectList?.length) {
        this.props.fetchAllEmpAssignSubjects({
          schoolId: globalSchool.schoolId,
          token: this.props.loggedUserToken,
        });
      }
    } else {
      this.showWarning('Please select School', 'warning');
    }
  }

  // The batch the page is for. Normally set already (the batch picker in the top bar); when it is not, the running year's batch is looked
  // up, the way the Students and Events pages do. Without it the page could not read the batch's classes and said it had none.
  ensureBatch = async () => {
    if (getGlobalCurrentBatchUtils().batchId) return;
    const schoolId = getGlobalSchoolUtils()?.schoolId;
    if (!schoolId) return;
    const { startYear, endYear } = getCurrentYearBatchUtils();
    await store.dispatch(
      fetchCurrentBatchByYearService({ token: this.props.loggedUserToken, schoolId, startYear, endYear })
    );
  };

  // All the batch's subjects in one call. With a copy from last time on screen it is read quietly (no skeleton), then replaces it.
  loadAllSubjects = async () => {
    const { batchId } = getGlobalCurrentBatchUtils();
    const schoolId = this.state.schoolId || getGlobalSchoolUtils()?.schoolId;
    if (!batchId || !schoolId) {
      this.setState({ allSubjectsFetching: false });
      return;
    }
    if (!cacheGet(this.cacheKey())?.allSubjects) this.setState({ allSubjectsFetching: true });
    try {
      const allSubjects = await fetchBatchSubjectsApi({ schoolId, batchId, token: this.props.loggedUserToken });
      this.setState({ allSubjects });
      cacheSet(this.cacheKey(), { ...cacheGet(this.cacheKey()), allSubjects });
    } catch (err) {
      this.showWarning(formResMessage(err), 'error');
    } finally {
      this.setState({ allSubjectsFetching: false });
    }
  };

  fetchGenSubjectAndCodes = (globalSchool = getGlobalSchoolUtils(), refetchAgain) => {
    if (!this.props?.subjectCodes?.length || refetchAgain) {
      this.props.fetchGenSubjectAndCodes({
        schoolId: globalSchool.schoolId,
        token: this.props.loggedUserToken,
      });
    }
  };

  fetchCourseSubjects = async (courseId, canFetchAgain) => {
    if (!this.state.courseId || this.state.courseId !== courseId || (courseId && canFetchAgain)) {
      this.isLoading('courseSubjectsFetching', true);
      await this.props.fetchCourseSubjects({
        courseId,
        token: this.props.loggedUserToken,
      });
      this.isLoading('courseSubjectsFetching', false);
    }
  };

  fetchBatchClassAndSubjects = async (canFetchAgain, passCourseId) => {
    const globalSchool = getGlobalSchoolUtils();
    const { batchId } = getGlobalCurrentBatchUtils();
    const { courseId: stateCourseId } = this.state;
    if (batchId) {
      let courseList = [];
      if (!stateCourseId) {
        courseList =
          !this.props.batchCourseList?.length || canFetchAgain
            ? await this.props.fetchBatchCourses({
                schoolId: globalSchool.schoolId,
                batchId,
                token: this.props.loggedUserToken,
              })
            : this.props.batchCourseList;
      }
      if (passCourseId || courseList?.length || stateCourseId || canFetchAgain) {
        const courseId = passCourseId || stateCourseId || courseList?.[0]?.courseId;
        this.fetchCourseSubjects(courseId, canFetchAgain);
        if (!passCourseId && !stateCourseId && courseId) {
          this.setState({ courseId });
        }
      }
    }
  };

  formModalOpen = () => this.setState({ isModalOpen: true });

  // "Add Subject": the dialog needs the batch's classes to pick from. They are normally loaded with the page, but when they were not
  // (the batch was not known yet, or the list was cleared by a batch switch) the dialog opened with an empty class list that could
  // not be chosen from. So they are read here when missing, the class chosen in the filter (or the first) is preselected, and a
  // batch with no classes says so instead of opening a dialog that cannot be used.
  openAddSubject = async () => {
    await this.ensureBatch();
    const { batchId } = getGlobalCurrentBatchUtils();
    let classes = this.props.batchCourseList;
    if (!classes?.length && batchId) {
      classes = await this.props.fetchBatchCourses({
        schoolId: this.state.schoolId || getGlobalSchoolUtils()?.schoolId,
        batchId,
        token: this.props.loggedUserToken,
      });
    }
    if (!classes?.length) {
      this.showWarning(
        'No classes found for this batch. Reload the page, or add a class first (Classes page).',
        'warning'
      );
      return;
    }
    const wanted = this.state.filterClass || this.state.courseId || classes[0].courseId;
    if (wanted !== this.state.courseId || !this.props.courseSubjects) {
      this.handleSelectChange({ value: wanted });
    }
    this.setState({ isModalOpen: true });
  };

  formModalClose = () => {
    this.setState({ isModalOpen: false });
  };

  openAssignTeacherModal = subject => this.setState({ isAssignTeacherModalOpen: true, assignTeacherSubject: subject });

  closeAssignTeacherModal = () => this.setState({ isAssignTeacherModalOpen: false, assignTeacherSubject: null });

  assignTeacherSuccess = () => {
    this.closeAssignTeacherModal();
    this.showWarning(`${employeeStatic} assigned successfully`, 'success');
    const globalSchool = getGlobalSchoolUtils();
    this.props.fetchAllEmpAssignSubjects({ schoolId: globalSchool.schoolId, token: this.props.loggedUserToken });
  };

  saveSubject = data => {
    const { loggedUserId, loggedUserToken } = this.props;
    return this.props.saveSubject({
      courseId: data?.course?.courseId,
      postData: data?.subjectList,
      adminId: loggedUserId,
      token: loggedUserToken,
    });
  };

  fetchSubject = subjectId => {
    return this.props.fetchSubject({ subjectId, token: this.props.loggedUserToken }).then(() => this.formModalOpen());
  };

  updateSubject = data => {
    return this.props.updateSubject({
      subjectId: data.subjectId,
      postData: data,
      adminId: this.props.loggedUserId,
      token: this.props.loggedUserToken,
    });
  };

  subjectUpdateSuccess = actionParam => {
    this.setState({ isModalOpen: false });
    this.showWarning(actionParam === 'add' ? 'Subject added successfully' : 'Subject Updated successfully', 'success');
    this.refreshSubjects();
  };

  showWarning = (message, type) => {
    store.dispatch(showToast(message, type));
  };

  deleteSubject = subjectId => {
    return this.props
      .deleteSubject({ subjectId, token: this.props.loggedUserToken })
      .then(() => {
        this.refreshSubjects();
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  // after a change: load the subjects again (the table, and the chosen class's list the add form checks against)
  refreshSubjects = () => {
    this.loadAllSubjects();
    this.fetchBatchClassAndSubjects(true);
  };

  handleSelectChange = selectItem => {
    if (!this.state.courseId || selectItem.value !== this.state.courseId) {
      this.setState(prevState => ({
        ...prevState,
        courseId: selectItem.value,
      }));
      this.fetchBatchClassAndSubjects(true, selectItem.value);
    }
  };

  // subjectId -> assigned teacher (raw employee record), flattened from the school-wide
  // teacher/subject assignment list. Built here rather than stored, since it's cheap and
  // only needed for display.
  getSubjectTeacherMap = () => {
    const { empAssignSubjectList = [] } = this.props;
    const { employees = [] } = this.state;
    const employeeById = employees.reduce((acc, emp) => {
      acc[emp.employeeId] = emp;
      return acc;
    }, {});
    return empAssignSubjectList.reduce((acc, teacherAssign) => {
      // someone who is not on the teachers list (a worker given a subject) still counts as assigned
      const emp = employeeById[teacherAssign.employeeId] || { name: 'Other staff', code: '' };
      (teacherAssign.subjects || []).forEach(subjectAssign => {
        acc[subjectAssign.subjectId] = emp;
      });
      return acc;
    }, {});
  };

  render() {
    const {
      isModalOpen,
      courseId,
      allSubjects,
      allSubjectsFetching,
      filterClass,
      filterText,
      onlyNoTeacher,
      isAssignTeacherModalOpen,
      assignTeacherSubject,
      employees,
    } = this.state;
    const { batchCourseList, courseSubjects, subject, subjectCodes, history } = this.props;

    const subjectTeacherMap = this.getSubjectTeacherMap();
    const readOnly = this.isReadOnly();
    const codeSpan = code => <span style={{ color: '#bcbcbc', fontWeight: 'bold' }}> ({code})</span>;

    // the subjects of this batch's classes, in the order of the classes
    const classOrder = (batchCourseList || []).map(c => c.courseId);
    const inBatch = classOrder.length
      ? allSubjects.filter(el => classOrder.includes(el.course?.courseId))
      : allSubjects;
    const all = [...inBatch]
      .sort(
        (a, b) =>
          classOrder.indexOf(a.course?.courseId) - classOrder.indexOf(b.course?.courseId) ||
          String(a.name).localeCompare(String(b.name))
      )
      .map(el => ({ ...el, teacher: subjectTeacherMap[el.subjectId] }));
    const assignedIds = new Set(
      (this.props.empAssignSubjectList || []).filter(t => t.subjects?.length).map(t => t.employeeId)
    );
    const freeTeachers = employees.filter(e => !assignedIds.has(e.employeeId));
    const noTeacher = all.filter(el => !el.teacher).length;
    const q = filterText.trim().toLowerCase();
    const shown = all.filter(
      el =>
        (!filterClass || el.course?.courseId === filterClass) &&
        (!onlyNoTeacher || !el.teacher) &&
        (!q ||
          `${el.name} ${el.subjectCode} ${el.teacher?.name || ''} ${el.course?.name || ''}`.toLowerCase().includes(q))
    );
    const classOptions = (batchCourseList || []).map(c => ({ value: c.courseId, label: c.name }));
    // the tile counts the batch's classes; until they are known it counts the classes the subjects belong to
    const classCount = classOptions.length || new Set(all.map(el => el.course?.courseId)).size;
    const goTeacherSubjects = event => {
      event.preventDefault();
      history.push('/admin/subjects?tab=teacher-subjects');
    };

    return (
      <div className="content">
        <div className="rui-stats">
          <div className="rui-stat">
            <div className="rui-stat-n">{allSubjectsFetching ? '–' : all.length}</div>
            <div className="rui-stat-l">
              subjects in {classCount} {coursesStatic.toLowerCase()}
            </div>
          </div>
          <div className="rui-stat">
            <div className={`rui-stat-n${noTeacher ? ' warn' : ''}`}>{allSubjectsFetching ? '–' : noTeacher}</div>
            <div className="rui-stat-l">subjects have no {employeeStatic.toLowerCase()}</div>
            {noTeacher > 0 && (
              <button type="button" className="rui-stat-link" onClick={() => this.setState({ onlyNoTeacher: true })}>
                Show them
              </button>
            )}
          </div>
          {!readOnly && employees.length > 0 && (
            <div className="rui-stat">
              <div className={`rui-stat-n${freeTeachers.length ? ' warn' : ''}`}>{freeTeachers.length}</div>
              <div className="rui-stat-l">{employeeStatic.toLowerCase()}s have no subject yet</div>
              <a className="rui-stat-link" href="/admin/subjects?tab=teacher-subjects" onClick={goTeacherSubjects}>
                Open {employeeStatic} subjects
              </a>
            </div>
          )}
        </div>
        <div
          className="rui-listbar"
          style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap', marginBottom: 12 }}>
          <div style={{ width: 200 }}>
            <FilterSelect
              options={classOptions}
              value={filterClass}
              placeholder={`All ${coursesStatic.toLowerCase()}`}
              onChange={value => this.setState({ filterClass: value })}
            />
          </div>
          <Input
            style={{ width: 230 }}
            value={filterText}
            placeholder={`Search subject or ${employeeStatic.toLowerCase()}`}
            onChange={e => this.setState({ filterText: e.target.value })}
          />
          <div className="rui-chips" style={{ marginTop: 0 }}>
            <button
              type="button"
              className={onlyNoTeacher ? 'on' : ''}
              onClick={() => this.setState({ onlyNoTeacher: !onlyNoTeacher })}>
              No {employeeStatic.toLowerCase()} yet
            </button>
          </div>
          {!readOnly && (
            <div style={{ marginLeft: 'auto' }}>
              <CustomButton onClick={this.openAddSubject} name="Add Subject" />
            </div>
          )}
        </div>
        <div className="rui-listarea">
          <MuiTable
            tableHeaders={['Class', 'Subject & Code', employeeStatic, 'Action'].filter(
              head => !(readOnly && head === 'Action')
            )}
            tableBodyData={{
              content: shown.map(el => ({
                ...el,
                className: el.course?.name,
                nameAndCode: (
                  <>
                    {el.name} {codeSpan(el.subjectCode)}
                  </>
                ),
                assignedTeacherName: el.teacher ? (
                  <>
                    {el.teacher.name} {el.teacher.code && codeSpan(el.teacher.code)}
                  </>
                ) : (
                  <span style={{ color: '#bcbcbc', fontStyle: 'italic' }}>Unassigned</span>
                ),
              })),
            }}
            bodyColumns={['className', 'nameAndCode', 'assignedTeacherName', 'action'].filter(
              column => !(readOnly && column === 'action')
            )}
            dropDownActions={readOnly ? [] : ['edit']}
            idName="subjectId"
            fetchItem={this.fetchSubject}
            deleteItem={this.deleteSubject}
            hidePagination
            isLoading={allSubjectsFetching}
            renderRowExtra={
              readOnly
                ? null
                : item => (
                    <CustomButton
                      variant="outlined"
                      color="default"
                      size="small"
                      onClick={() => this.openAssignTeacherModal(item)}
                      name={item.teacher ? `Change ${employeeStatic}` : `Assign ${employeeStatic}`}
                    />
                  )
            }
          />
        </div>
        {!readOnly && (
          <>
            <SubjectFormModal
              courseId={courseId}
              isModalOpen={isModalOpen}
              formModalCloseProp={this.formModalClose}
              courses={batchCourseList}
              saveSubject={this.saveSubject}
              subject={subject}
              updateSubject={this.updateSubject}
              subjectUpdateSuccess={this.subjectUpdateSuccess}
              subjectCodes={subjectCodes}
              refreshSubjectCodes={() => this.fetchGenSubjectAndCodes(undefined, true)}
              handlePassCourse={cId => this.handleSelectChange({ value: cId })}
              courseSubjects={courseSubjects}
            />
            <AssignTeacherSubjectModal
              isOpen={isAssignTeacherModalOpen}
              subject={assignTeacherSubject}
              allTeachers={employees}
              assignedCounts={Object.fromEntries(
                (this.props.empAssignSubjectList || []).map(t => [t.employeeId, t.subjects?.length || 0])
              )}
              token={this.props.loggedUserToken}
              onClose={this.closeAssignTeacherModal}
              onSuccess={this.assignTeacherSuccess}
              showWarning={this.showWarning}
            />
          </>
        )}
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    subjectList: state.subjects.subjectList,
    subject: state.subjects.subject,
    empAssignSubjectList: state.employees.empAssignSubjectList,
    empSubjectList: state.subjects.empSubjectList,
    // Config
    subjectCodes: state.config.subjectCodes,
    // Courses
    batchCourseList: state.courses.batchCourseList,
    courseSubjects: state.subjects.courseSubjects,
    currentBatch: state.batches.currentBatch?.batchId ? state.batches.currentBatch : undefined,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchBatchCourses: data => dispatch(fetchBatchCourseService(data)),
    saveSubject: data => dispatch(saveSubjectService(data)),
    fetchSubject: data => dispatch(fetchSubjectService(data)),
    updateSubject: data => dispatch(updateSubjectService(data)),
    deleteSubject: data => dispatch(deleteSubjectService(data)),

    // Config
    fetchGenSubjectAndCodes: data => dispatch(fetchGenSubjectAndCodesService(data)),
    // Course subjs
    fetchCourseSubjects: data => dispatch(fetchCourseSubjectsService(data)),
    // Teachers
    fetchAllEmpAssignSubjects: data => dispatch(fetchAllEmpAssignSubjectsService(data)),
  };
};

export default withRouter(connect(mapStateToProps, mapDispatchToProps)(SubjectPage));
