// Pure helpers of the "Assign subjects to teachers" page (views/admin/Subject/AssignSubjectsPage.jsx).
// A row is one subject of one class: { subjectId, subjectName, subjectCode, courseId, courseName, courseCode, employeeId, teacherName }.

export const SHOW = { ALL: '', UNASSIGNED: 'un', ASSIGNED: 'as', MINE: 'mine', OTHERS: 'others' };

const same = (a, b) => String(a) === String(b);

// The rows the filters leave. activeId is the teacher chosen on the left (for "Selected teacher's" / "Other teachers").
export const filterSubjects = (
  rows,
  { courseId = '', subjectName = '', show = SHOW.ALL, text = '' } = {},
  activeId = null
) => {
  const q = String(text || '')
    .trim()
    .toLowerCase();
  return (rows || []).filter(row => {
    if (courseId && !same(row.courseId, courseId)) return false;
    if (subjectName && row.subjectName !== subjectName) return false;
    if (show === SHOW.UNASSIGNED && row.employeeId) return false;
    if (show === SHOW.ASSIGNED && !row.employeeId) return false;
    if (show === SHOW.MINE && !same(row.employeeId, activeId)) return false;
    if (show === SHOW.OTHERS && (!row.employeeId || same(row.employeeId, activeId))) return false;
    if (q) {
      const hay = [row.courseName, row.courseCode, row.subjectName, row.subjectCode, row.teacherName]
        .join(' ')
        .toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });
};

// How many subjects each teacher has: { employeeId: count }.
export const countByTeacher = rows =>
  (rows || []).reduce((acc, row) => {
    if (row.employeeId) acc[row.employeeId] = (acc[row.employeeId] || 0) + 1;
    return acc;
  }, {});

// Class and subject choices for the two filter dropdowns (classes in code order, subjects by name).
export const filterOptions = rows => {
  const classes = new Map();
  const subjects = new Set();
  [...(rows || [])]
    .sort((a, b) => String(a.courseCode).localeCompare(String(b.courseCode), undefined, { numeric: true }))
    .forEach(row => {
      if (!classes.has(row.courseId)) classes.set(row.courseId, row.courseName);
      subjects.add(row.subjectName);
    });
  return {
    classes: [...classes].map(([value, label]) => ({ value, label })),
    subjects: [...subjects].sort(),
  };
};

// Shift+click: every visible row between two positions, ticked or unticked together (the state of the row clicked last).
export const toggleRange = (ticked, visible, from, to) => {
  const next = { ...ticked };
  const [a, b] = from <= to ? [from, to] : [to, from];
  const on = !ticked[visible[to].subjectId];
  for (let i = a; i <= b; i += 1) {
    if (on) next[visible[i].subjectId] = true;
    else delete next[visible[i].subjectId];
  }
  return next;
};

// What assigning the ticked rows to a teacher will do: how many, and how many already have another teacher (they are replaced).
export const assignSummary = (rows, activeId) => ({
  total: rows.length,
  replacing: rows.filter(row => row.employeeId && !same(row.employeeId, activeId)).length,
});
