import React, { useEffect, useRef, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Input } from 'reactstrap';
import CustomButton from '../../../../components/CustomButton';
import { employeeStatic } from '../../../../config/constants';
import { formEmpSelectList, formResMessage, getGlobalCurrentBatchUtils, getGlobalSchoolUtils } from 'utils/commonFunc';
import { fetchTeacherBySubjectApi } from 'actions/admin/subjects';
import {
  fetchEmpAssignSubjectApi,
  saveEmpAssignSubjectService,
  updateEmpAssignSubjectService,
} from 'actions/admin/employees';

// Per-subject "who teaches this" modal, opened from a row on the Subjects page. Unlike
// EmpSubjectAssignModal (Employee page, teacher-centric: pick a teacher then multi-select
// their subjects), this is subject-centric: the subject is fixed, pick the one teacher for
// it. It's built on the same two assign/update endpoints EmpSubjectAssignModal already
// uses, just fed a single-subject payload instead of the teacher's whole subject list.
//
// The picker lists every school teacher (not just unassigned ones) - a teacher can teach
// more than one subject, so being assigned elsewhere should never make them unpickable
// here. "Who's still free" lives separately on the Subjects page itself.
const AssignTeacherSubjectModal = ({
  isOpen,
  subject,
  allTeachers,
  assignedCounts = {},
  token,
  onClose,
  onSuccess,
  showWarning,
}) => {
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [currentTeacherSubjectId, setCurrentTeacherSubjectId] = useState(null);
  const [selectedTeacher, setSelectedTeacher] = useState(null);
  const [initialTeacherId, setInitialTeacherId] = useState(null);
  const [search, setSearch] = useState('');
  const chosenRef = useRef(null);

  const teacherOptions = formEmpSelectList(allTeachers) || [];

  useEffect(() => {
    if (isOpen && subject) {
      const { batchId } = getGlobalCurrentBatchUtils();
      setLoading(true);
      setSelectedTeacher(null);
      setSearch('');
      setCurrentTeacherSubjectId(null);
      setInitialTeacherId(null);
      fetchTeacherBySubjectApi({ subjectId: subject.subjectId, token })
        .then(teacherRes => {
          const currentTeacher = teacherRes?.data;
          if (currentTeacher?.employeeId) {
            const currentOption =
              teacherOptions.find(el => el.employeeId === currentTeacher.employeeId) ||
              formEmpSelectList([currentTeacher])[0];
            setSelectedTeacher(currentOption);
            setInitialTeacherId(currentTeacher.employeeId);
            fetchEmpAssignSubjectApi({ employeeId: currentTeacher.employeeId, batchId, token }).then(res => {
              const match = res?.data?.find(el => el.subjectId === subject.subjectId);
              setCurrentTeacherSubjectId(match?.teacherSubjectId || null);
            });
          }
        })
        .catch(err => showWarning(formResMessage(err), 'error'))
        .finally(() => setLoading(false));
    }
  }, [isOpen, subject]);

  // the teacher who has the subject now is scrolled into view when the list opens
  useEffect(() => {
    if (!loading && chosenRef.current) chosenRef.current.scrollIntoView({ block: 'center' });
  }, [loading, isOpen]);

  const needle = search.trim().toLowerCase();
  const shownTeachers = [...teacherOptions]
    .filter(option => !needle || String(option.label).toLowerCase().includes(needle))
    .sort((a, b) => String(a.label).localeCompare(String(b.label)));

  const handleSubmit = e => {
    e.preventDefault();
    if (!selectedTeacher) return;
    const globalSchool = getGlobalSchoolUtils();
    setSaving(true);
    const postData = {
      employeeId: selectedTeacher.employeeId,
      schoolId: globalSchool.schoolId,
      subjects: [
        {
          subjectId: subject.subjectId,
          ...(initialTeacherId === selectedTeacher.employeeId && currentTeacherSubjectId
            ? { teacherSubjectId: currentTeacherSubjectId }
            : {}),
        },
      ],
    };
    const isUpdate = initialTeacherId === selectedTeacher.employeeId && currentTeacherSubjectId;
    const request = isUpdate
      ? updateEmpAssignSubjectService({ postData, token })
      : saveEmpAssignSubjectService({ postData, token });
    request()
      .then(() => {
        setSaving(false);
        onSuccess();
      })
      .catch(err => {
        setSaving(false);
        showWarning(formResMessage(err), 'error');
      });
  };

  const currentTeacher = teacherOptions.find(option => option.employeeId === initialTeacherId);

  return (
    <Modal size="md" isOpen={isOpen} centered>
      <form onSubmit={handleSubmit}>
        <ModalHeader>Assign {employeeStatic}</ModalHeader>
        <ModalBody>
          <div
            style={{
              background: '#faf5fd',
              border: '1px solid #ece6f2',
              borderRadius: 12,
              padding: '10px 14px',
              marginBottom: 14,
            }}>
            <div style={{ fontWeight: 'bold' }}>
              {subject?.name} <span style={{ color: '#98a2ad' }}>({subject?.subjectCode})</span>
            </div>
            <div style={{ fontSize: 12, color: '#6b778a', marginTop: 2 }}>
              {subject?.course?.name ? `${subject.course.name} · ` : ''}
              {loading
                ? 'Checking who teaches it...'
                : currentTeacher
                ? `Now taught by ${currentTeacher.label}`
                : `No ${employeeStatic.toLowerCase()} yet`}
            </div>
          </div>
          <Input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder={`Search ${employeeStatic.toLowerCase()} name or code`}
            style={{ height: 36, borderRadius: 12, fontSize: 13, marginBottom: 8 }}
          />
          <div style={{ height: 320, overflowY: 'auto', border: '1px solid #e8e3f0', borderRadius: 12 }}>
            {shownTeachers.map(option => {
              const chosen = selectedTeacher?.employeeId === option.employeeId;
              const count = assignedCounts[option.employeeId] || 0;
              return (
                <div
                  key={option.employeeId}
                  ref={chosen ? chosenRef : null}
                  role="radio"
                  aria-checked={chosen}
                  tabIndex={0}
                  onClick={() => setSelectedTeacher(option)}
                  onKeyDown={e => (e.key === 'Enter' || e.key === ' ') && setSelectedTeacher(option)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 10,
                    padding: '9px 12px',
                    cursor: 'pointer',
                    borderBottom: '1px solid #f3eff7',
                    background: chosen ? '#ede1f7' : '#fff',
                  }}>
                  <span
                    aria-hidden="true"
                    style={{
                      width: 16,
                      height: 16,
                      flex: 'none',
                      borderRadius: '50%',
                      border: `2px solid ${chosen ? '#7b1fa2' : '#c9c1d6'}`,
                      boxShadow: chosen ? 'inset 0 0 0 3px #ede1f7, inset 0 0 0 8px #7b1fa2' : 'none',
                    }}
                  />
                  <span style={{ flex: 1, minWidth: 0 }}>
                    <span style={{ fontWeight: chosen ? 'bold' : 500 }}>{option.name || option.label}</span>
                    {option.code && <small style={{ marginLeft: 6, color: '#9ca3af' }}>{option.code}</small>}
                  </span>
                  <span
                    style={{
                      fontSize: 12,
                      fontWeight: 700,
                      borderRadius: 999,
                      padding: '1px 9px',
                      background: count ? '#f1ecf7' : '#ffe8b8',
                      color: count ? '#1b1030' : '#8a5a00',
                    }}>
                    {count ? `${count} subject${count === 1 ? '' : 's'}` : 'No subject yet'}
                  </span>
                </div>
              );
            })}
            {loading && <div className="text-muted p-3">Loading...</div>}
            {!loading && !shownTeachers.length && (
              <div className="text-muted p-3">No {employeeStatic.toLowerCase()} found.</div>
            )}
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={saving || loading || !selectedTeacher} loading={saving} name="Save" />
          <CustomButton
            className="ml-2"
            type="button"
            color="default"
            disabled={saving}
            onClick={onClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default AssignTeacherSubjectModal;
